"use strict";
(()=>{const sheet=document.querySelector('#detail-sheet'),heading=document.querySelector('#sheet-heading'),reduced=matchMedia('(prefers-reduced-motion:reduce)');let opener=null,role='pt';
function setRole(next){role=next;document.querySelectorAll('[data-role]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.role===role)));document.querySelectorAll('[data-pt-only]').forEach(el=>el.hidden=role!=='pt');document.querySelectorAll('[data-trainee-only]').forEach(el=>el.hidden=role!=='trainee');document.querySelector('.profile-rail').hidden=role!=='pt';document.querySelector('.profile-surface').classList.toggle('learner-surface',role==='trainee');document.querySelector('[data-role-label]').textContent=role==='pt'?'Hồ sơ trong không gian PT':'Thông tin được chia sẻ với bạn';const link=document.querySelector('[data-profile-link]');link.href=role==='pt'?'/demo/#pt/profile':'/demo/#trainee/profile';document.querySelector('#page-status').textContent=role==='pt'?'Đang xem hồ sơ PT, dữ liệu giả.':'Đang xem phần thông tin được chia sẻ với học viên, dữ liệu giả.';}
document.querySelectorAll('[data-role]').forEach(b=>{b.disabled=false;b.addEventListener('click',()=>setRole(b.dataset.role));});
function open(kind,source){if(!sheet.open)opener=source;document.querySelectorAll('[data-sheet]').forEach(el=>el.hidden=el.dataset.sheet!==kind);heading.textContent={appointment:'Cùng một buổi hẹn',report:'Đối chiếu bản nháp',chat:'Trao đổi với Linh'}[kind];if(!sheet.open)sheet.showModal();sheet.scrollTop=0;sheet.querySelector('[data-close]').focus({preventScroll:true});}
function close(){sheet.close();if(opener?.isConnected)opener.focus({preventScroll:true});}
document.querySelectorAll('[data-open]').forEach(button=>{button.disabled=false;button.addEventListener('click',()=>open(button.dataset.open,button));});sheet.querySelector('[data-close]').addEventListener('click',close);sheet.addEventListener('cancel',event=>{event.preventDefault();close();});sheet.addEventListener('click',event=>{if(event.target===sheet){const r=sheet.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)close();}});
sheet.addEventListener('keydown',event=>{if(event.key!=='Tab')return;const nodes=[...sheet.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled)')].filter(el=>el.getClientRects().length);if(!nodes.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}});
const check=document.querySelector('#review-check'),confirm=document.querySelector('#confirm-review');check.addEventListener('change',()=>confirm.disabled=!check.checked);confirm.addEventListener('click',()=>{if(!check.checked)return;document.querySelector('.review-result').textContent='Đã mô phỏng xác nhận. Không lưu hoặc thay đổi hồ sơ thật.';confirm.disabled=true;check.disabled=true;});
// Chart labels use actual CSS-pixel geometry so phone data stays readable.
const plot=document.querySelector('.progress-plot svg');plot.classList.add('responsive-plot');const ns='http://www.w3.org/2000/svg';
function drawPlot(){const width=Math.max(190,Math.round(plot.getBoundingClientRect().width)),left=30,right=width-10,top=12,bottom=132;plot.setAttribute('viewBox','0 0 '+width+' 170');plot.replaceChildren();const make=(name,attrs,text)=>{const el=document.createElementNS(ns,name);Object.entries(attrs).forEach(([key,value])=>el.setAttribute(key,String(value)));if(text)el.textContent=text;plot.append(el);return el;};for(let i=0;i<4;i++){const y=top+i*40;make('path',{d:'M'+left+' '+y+'H'+right,class:'grid'});make('text',{x:0,y:y+5,class:'axis','font-size':13},String(73-i));}const dates=['02/10','09/10','16/10','23/10'],values=[72.1,71.6,71.0,70.4],points=values.map((value,i)=>[left+i*(right-left)/3,bottom-(value-70)*40]);dates.forEach((date,i)=>make('text',{x:points[i][0],y:163,class:'axis','text-anchor':i===0?'start':i===3?'end':'middle','font-size':13},width<300?date.slice(0,2):date));make('path',{d:points.map((point,i)=>(i?'L':'M')+point[0]+' '+point[1]).join(' '),class:'series'});const end=points[3];make('circle',{cx:end[0],cy:end[1],r:3.5,class:'series-end'});}
new ResizeObserver(drawPlot).observe(plot);drawPlot();
// The only entrance is the appointment specimen. Reading never waits for motion.
if(!reduced.matches)document.querySelector('.appointment-peek').classList.add('arrive');
})();